#include "tigersheets/session.hpp"
#include "tigersheets/worksheet_validation.hpp"
#include "tigersheets/calculation.hpp"
#include <iostream>
#include <stdexcept>
#include <vector>
using namespace tigersheets;
namespace {
void require(bool value,const std::string& message){if(!value)throw std::runtime_error(message);}
Json fixture(){auto book=WorkbookSession().snapshot();book["sheets"].push_back({{"id","input"},{"name","Input"},{"cells",Json::array({{{"row",3},{"col",2},{"input","0.1"},{"style",{{"numberFormat","0%"}}}},{{"row",4},{"col",2},{"input","0.2"},{"style",{{"numberFormat","0%"}}}}})}});return book;}
Json rule(){return {{"type","list"},{"range",{{"row1",3},{"col1",3},{"row2",3},{"col2",3}}},{"formula1","=Input!$B$3:$B$4"},{"allowBlank",true}};}
void sessionRule(){WorkbookSession session(fixture());const auto before=session.snapshot();std::string error;require(session.apply(0,Json::array({{{"type","set_data_validation"},{"sheet","sheet-1"},{"validation",rule()}}}),&error),"native list validation transaction: "+error);require(session.snapshot().at("sheets")[0].at("dataValidations")==Json::array({rule()}),"validation metadata belongs to its target worksheet");require(session.undo()&&session.snapshot().at("sheets")==before.at("sheets"),"one Undo restores worksheet validation metadata");require(session.redo()&&session.snapshot().at("sheets")[0].at("dataValidations")==Json::array({rule()}),"Redo restores native list validation");}
void typedOptions(){auto book=fixture();book["sheets"][1]["cells"].push_back({{"row",5},{"col",2},{"input","=B3*3"},{"style",{{"numberFormat","0%"}}}});auto validation=rule();validation["formula1"]="=Input!$B$3:$B$5";CalculationEngine engine;const auto calculated=engine.calculate(book);const auto options=worksheetValidationOptions(book,calculated,"sheet-1",validation);require(options.size()==3,"list resolves all three live source cells");require(options[0].at("label")=="10%"&&options[0].at("input")=="0.1"&&options[0].at("type")=="number"&&options[0].at("value")==0.1,"percentage option retains numeric decimal input and formatted display");require(options[2].at("label")=="30%"&&options[2].at("value").get<double>()>0.299&&options[2].at("value").get<double>()<0.301,"formula list source uses its calculated numeric result and percent style");}
void lookup(){auto sheet=fixture().at("sheets")[0];auto validation=rule();validation["range"]["row2"]=5;sheet["dataValidations"]=Json::array({validation});const auto* found=worksheetListValidationAt(sheet,5,3);require(found&&found->at("formula1")==validation.at("formula1"),"validation lookup includes the final target cell");require(!worksheetListValidationAt(sheet,6,3)&&!worksheetListValidationAt(sheet,3,2),"validation lookup excludes cells outside its target");}
void stalePercentLiterals(){auto book=fixture();book["sheets"][1]["cells"][0]["input"]="10%";book["sheets"][1]["cells"][1]["input"]="'00123";const auto options=worksheetValidationOptions(book,Json::object(),"sheet-1",rule());require(options[0].at("type")=="number"&&options[0].at("value")==0.1&&options[0].at("input")=="0.1"&&options[0].at("label")=="10%","percent source literals stay numeric while a new calculation is pending");require(options[1].at("type")=="string"&&options[1].at("input")=="'00123"&&options[1].at("label")=="00123","literal text options retain leading zeros when chosen");}
void invalidRulesAreAtomic(){std::vector<Json> invalid;for(const auto& change:std::vector<std::pair<std::string,Json>>{{"row1",0},{"row1",1.5},{"row2",1048577},{"col2",16385},{"row1",4}}){auto bad=rule();bad["range"][change.first]=change.second;invalid.push_back(bad);}for(const auto* source:{"=Missing!A1:A3","=Input!A1:B2","=Input!A1:A10001","=[Other.xlsx]Input!A1:A3","=SUM(Input!B3:B4)"}){auto bad=rule();bad["formula1"]=source;invalid.push_back(bad);}auto bad=rule();bad["allowBlank"]="true";invalid.push_back(bad);bad=rule();bad["type"]="whole";invalid.push_back(bad);
 for(const auto& validation:invalid){WorkbookSession session(fixture());const auto before=session.snapshot();std::string error;require(!session.apply(0,Json::array({{{"type","set_cell"},{"sheet","sheet-1"},{"row",1},{"col",1},{"input","rollback"}},{{"type","set_data_validation"},{"sheet","sheet-1"},{"validation",validation}}}),&error),"invalid validation must reject the entire transaction");require(session.snapshot()==before&&!session.canUndo()&&!error.empty(),"invalid validation preserves revision, contents and history with a diagnostic");auto imported=fixture();imported["sheets"][0]["dataValidations"]=Json::array({validation});bool rejected=false;try{WorkbookSession loaded(imported);}catch(const std::exception&){rejected=true;}require(rejected,"constructor uses the same validation metadata checks");}
}
void sourceRename(){auto book=fixture();book["sheets"][0]["dataValidations"]=Json::array({rule()});WorkbookSession session(book);std::string error;const auto renamed=session.apply(0,Json::array({{{"type","rename_sheet"},{"sheet","input"},{"name","Input choices"}}}),&error);require(renamed,"renaming a managed list source updates its reference: "+error);require(session.snapshot().at("sheets")[0].at("dataValidations")[0].at("formula1")=="='Input choices'!$B$3:$B$4","validation source is quoted for its new worksheet name");require(session.undo()&&session.snapshot().at("sheets")==book.at("sheets"),"source rename and validation reference are one undo transaction");}
void structuralSafety(){for(const auto* affected:{"sheet-1","input"})for(const auto* operation:{"insert_rows","delete_rows","insert_columns","delete_columns"}){auto book=fixture();book["sheets"][0]["dataValidations"]=Json::array({rule()});WorkbookSession session(book);std::string error;require(!session.apply(0,Json::array({{{"type",operation},{"sheet",affected},{"index",1},{"count",1}}}),&error),"structural edits cannot silently move managed validation targets or sources");require(session.snapshot()==book&&!session.canUndo()&&error.find("validation")!=std::string::npos,"refused validation structural edit preserves cells and history with an explanation");}}
void replaceAndRemove(){WorkbookSession session(fixture());require(session.apply(0,Json::array({{{"type","set_data_validation"},{"sheet","sheet-1"},{"validation",rule()}}})),"create initial list rule");auto replacement=rule();replacement["formula1"]="=Input!$B$4";replacement["allowBlank"]=false;require(session.apply(1,Json::array({{{"type","set_data_validation"},{"sheet","sheet-1"},{"validation",replacement}}})),"replace the same target's list source");require(session.snapshot().at("sheets")[0].at("dataValidations")==Json::array({replacement}),"exact target replacement leaves one rule");const auto before=session.snapshot();auto overlapping=rule();overlapping["range"]["row2"]=4;require(!session.apply(2,Json::array({{{"type","set_data_validation"},{"sheet","sheet-1"},{"validation",overlapping}}}))&&session.snapshot()==before,"partly overlapping validation target is rejected atomically");require(session.apply(2,Json::array({{{"type","set_data_validation"},{"sheet","sheet-1"},{"range",replacement.at("range")},{"validation",nullptr}}})),"remove the selected list rule");require(!session.snapshot().at("sheets")[0].contains("dataValidations"),"removing the final list clears worksheet metadata");require(session.undo()&&session.snapshot().at("sheets")[0].at("dataValidations")==Json::array({replacement}),"removing a validation is one undoable transaction");}
}
int main(int argc,char** argv){try{const auto scenario=argc>1?std::string(argv[1]):std::string();if(scenario.empty()||scenario=="session")sessionRule();if(scenario.empty()||scenario=="options")typedOptions();if(scenario.empty()||scenario=="lookup")lookup();if(scenario.empty()||scenario=="percent")stalePercentLiterals();if(scenario.empty()||scenario=="invalid")invalidRulesAreAtomic();if(scenario.empty()||scenario=="rename")sourceRename();if(scenario.empty()||scenario=="structure")structuralSafety();if(scenario.empty()||scenario=="replace")replaceAndRemove();std::cout<<"worksheet validation tests passed\n";return 0;}catch(const std::exception& error){std::cerr<<"FAILED: "<<error.what()<<'\n';return 1;}}
